cat > crates/terminal_size/src/lib.rs <<'EOF'
//! Minimal terminal size detection (local replacement crate).

use std::os::unix::io::{AsRawFd, RawFd};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

fn size_of_fd(fd: RawFd) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        let rows = ws.ws_row;
        let cols = ws.ws_col;
        if rows > 0 && cols > 0 {
            Some((Width(cols), Height(rows)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal attached to stdout, stderr or stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(std::io::stdout().as_raw_fd())
        .or_else(|| size_of_fd(std::io::stderr().as_raw_fd()))
        .or_else(|| size_of_fd(std::io::stdin().as_raw_fd()))
}

/// Returns the size of the terminal attached to the given file descriptor.
pub fn terminal_size_of<Fd: AsRawFd>(fd: Fd) -> Option<(Width, Height)> {
    size_of_fd(fd.as_raw_fd())
}
EOF
