//! Command-line interface definition.

use clap::builder::{PossibleValuesParser, TypedValueParser};
use clap::{value_parser, Arg, ArgAction, ArgMatches, Command};
use regex::Regex;
use std::path::PathBuf;

use crate::enums::{DetailField, SortBase, Typ, Unit};

const ABOUT: &str = "pls is a prettier and powerful ls(1) for the pros.";
const LONG_ABOUT: &str = "pls is a prettier and powerful ls(1) for the pros.

Read docs: https://pls.cli.rs/
Get source: https://github.com/pls-rs/pls/
Sponsor: https://github.com/sponsors/dhruvkb/";

pub const DETAIL_NAMES: &[&str] = &[
    "dev", "ino", "nlink", "typ", "perm", "oct", "user", "uid", "group", "gid", "size", "blocks",
    "btime", "ctime", "mtime", "atime", "git", "none", "std", "all",
];

pub const TYP_NAMES: &[&str] = &[
    "dir",
    "symlink",
    "fifo",
    "socket",
    "block-device",
    "char-device",
    "file",
    "none",
    "all",
];

pub const SORT_NAMES: &[&str] = &[
    "dev", "ino", "nlink", "typ", "cat", "user", "uid", "group", "gid", "size", "blocks", "btime",
    "ctime", "mtime", "atime", "name", "cname", "ext", "inode_", "nlinks_", "typ_", "cat_",
    "user_", "uid_", "group_", "gid_", "size_", "blocks_", "btime_", "ctime_", "mtime_",
    "atime_", "name_", "cname_", "ext_", "none",
];

/// Parsed command-line arguments.
#[derive(Debug, Clone)]
pub struct Args {
    pub paths: Vec<PathBuf>,
    pub details: Vec<String>,
    pub header: bool,
    pub unit: Unit,
    pub grid: bool,
    pub down: bool,
    pub icon: bool,
    pub suffix: bool,
    pub sym: bool,
    pub collapse: bool,
    pub align: bool,
    pub types: Vec<String>,
    pub imp: i8,
    pub exclude: Option<Regex>,
    pub only: Option<Regex>,
    pub sort_bases: Vec<String>,
}

fn parse_regex(s: &str) -> Result<Regex, regex::Error> {
    Regex::new(s)
}

fn bool_arg(id: &'static str, short: char, help: &'static str, default: &'static str, heading: &'static str) -> Arg {
    Arg::new(id)
        .short(short)
        .long(id)
        .value_name(id.to_uppercase())
        .help(help)
        .action(ArgAction::Set)
        .value_parser(value_parser!(bool))
        .default_value(default)
        .help_heading(heading)
}

pub fn command() -> Command {
    Command::new("pls")
        .version("0.0.1-beta.9")
        .about(ABOUT)
        .long_about(LONG_ABOUT)
        .arg(
            Arg::new("paths")
                .value_name("PATHS")
                .help("the paths to list, each of which may be a file or directory")
                .action(ArgAction::Append)
                .num_args(1..)
                .value_parser(value_parser!(PathBuf))
                .default_value("."),
        )
        // Detail view
        .arg(
            Arg::new("details")
                .short('d')
                .long("det")
                .value_name("DETAILS")
                .help("the data points to show about each node")
                .action(ArgAction::Append)
                .value_parser(PossibleValuesParser::new(DETAIL_NAMES).map(|s| s.to_string()))
                .default_value("none")
                .help_heading("Detail view"),
        )
        .arg(bool_arg(
            "header",
            'H',
            "show headers above columnar data",
            "true",
            "Detail view",
        ))
        .arg(
            Arg::new("unit")
                .short('u')
                .long("unit")
                .value_name("UNIT")
                .help("the type of units to use for the node sizes")
                .action(ArgAction::Set)
                .value_parser(PossibleValuesParser::new(["binary", "decimal", "none"]).map(|s| s.to_string()))
                .default_value("binary")
                .help_heading("Detail view"),
        )
        // Grid view
        .arg(bool_arg(
            "grid",
            'g',
            "display node names in multiple columns",
            "false",
            "Grid view",
        ))
        .arg(bool_arg(
            "down",
            'D',
            "display node names column-first",
            "false",
            "Grid view",
        ))
        // Presentation
        .arg(bool_arg(
            "icon",
            'i',
            "display icons next to node names",
            "true",
            "Presentation",
        ))
        .arg(bool_arg(
            "suffix",
            'S',
            "display node type suffixes after the node name",
            "true",
            "Presentation",
        ))
        .arg(bool_arg("sym", 'l', "show symlink targets", "true", "Presentation"))
        .arg(bool_arg(
            "collapse",
            'c',
            "show dependent nodes as children of their principal nodes",
            "true",
            "Presentation",
        ))
        .arg(bool_arg(
            "align",
            'a',
            "align items accounting for leading dots",
            "true",
            "Presentation",
        ))
        // Filtering
        .arg(
            Arg::new("types")
                .short('t')
                .long("typ")
                .value_name("TYPES")
                .help("the set of node types to include in the output")
                .action(ArgAction::Append)
                .value_parser(PossibleValuesParser::new(TYP_NAMES).map(|s| s.to_string()))
                .default_value("all")
                .help_heading("Filtering"),
        )
        .arg(
            Arg::new("imp")
                .short('I')
                .long("imp")
                .value_name("IMP")
                .help("the importance cutoff to dim or hide unimportant files")
                .action(ArgAction::Set)
                .value_parser(value_parser!(i8))
                .default_value("0")
                .help_heading("Filtering"),
        )
        .arg(
            Arg::new("exclude")
                .short('e')
                .long("exclude")
                .value_name("EXCLUDE")
                .help("the pattern of files to selectively hide from the output")
                .action(ArgAction::Set)
                .value_parser(parse_regex)
                .help_heading("Filtering"),
        )
        .arg(
            Arg::new("only")
                .short('o')
                .long("only")
                .value_name("ONLY")
                .help("the pattern of files to exclusively show in the output")
                .action(ArgAction::Set)
                .value_parser(parse_regex)
                .help_heading("Filtering"),
        )
        // Sorting
        .arg(
            Arg::new("sort_bases")
                .short('s')
                .long("sort")
                .value_name("SORT_BASES")
                .help("the set of fields to sort by, trailing `_` reverses the direction")
                .action(ArgAction::Append)
                .value_parser(PossibleValuesParser::new(SORT_NAMES).map(|s| s.to_string()))
                .default_values(["cat", "cname"])
                .help_heading("Sorting"),
        )
}

fn get_bool(m: &ArgMatches, id: &str) -> bool {
    *m.get_one::<bool>(id).unwrap()
}

fn get_strings(m: &ArgMatches, id: &str) -> Vec<String> {
    m.get_many::<String>(id)
        .map(|v| v.cloned().collect())
        .unwrap_or_default()
}

pub fn parse() -> Args {
    let matches = command().get_matches();
    let unit = match matches.get_one::<String>("unit").map(|s| s.as_str()) {
        Some("decimal") => Unit::Decimal,
        Some("none") => Unit::None,
        _ => Unit::Binary,
    };
    Args {
        paths: matches
            .get_many::<PathBuf>("paths")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        details: get_strings(&matches, "details"),
        header: get_bool(&matches, "header"),
        unit,
        grid: get_bool(&matches, "grid"),
        down: get_bool(&matches, "down"),
        icon: get_bool(&matches, "icon"),
        suffix: get_bool(&matches, "suffix"),
        sym: get_bool(&matches, "sym"),
        collapse: get_bool(&matches, "collapse"),
        align: get_bool(&matches, "align"),
        types: get_strings(&matches, "types"),
        imp: *matches.get_one::<i8>("imp").unwrap(),
        exclude: matches.get_one::<Regex>("exclude").cloned(),
        only: matches.get_one::<Regex>("only").cloned(),
        sort_bases: get_strings(&matches, "sort_bases"),
    }
}

impl Args {
    /// Resolve the list of detail fields to display.
    pub fn detail_fields(&self) -> Vec<DetailField> {
        let mut out: Vec<DetailField> = Vec::new();
        for d in &self.details {
            let expanded: Vec<DetailField> = match d.as_str() {
                "none" => {
                    out.clear();
                    continue;
                }
                "std" => DetailField::std_fields(),
                "all" => DetailField::all_fields(),
                other => match DetailField::from_name(other) {
                    Some(f) => vec![f],
                    None => vec![],
                },
            };
            for f in expanded {
                out.retain(|x| *x != f);
                out.push(f);
            }
        }
        out
    }

    /// Resolve the set of node types to include.
    pub fn typ_set(&self) -> Vec<Typ> {
        let mut out: Vec<Typ> = Vec::new();
        for t in &self.types {
            let expanded: Vec<Typ> = match t.as_str() {
                "none" => {
                    out.clear();
                    continue;
                }
                "all" => Typ::all_real(),
                "dir" => vec![Typ::Dir],
                "symlink" => vec![Typ::Symlink],
                "fifo" => vec![Typ::Fifo],
                "socket" => vec![Typ::Socket],
                "block-device" => vec![Typ::BlockDevice],
                "char-device" => vec![Typ::CharDevice],
                "file" => vec![Typ::File],
                _ => vec![],
            };
            for f in expanded {
                if !out.contains(&f) {
                    out.push(f);
                }
            }
        }
        out
    }

    /// Resolve the sort bases.
    pub fn sorts(&self) -> Vec<SortBase> {
        let mut out = Vec::new();
        for s in &self.sort_bases {
            if s == "none" {
                out.clear();
                continue;
            }
            if let Some(b) = SortBase::from_name(s) {
                out.push(b);
            }
        }
        out
    }
}
