//! Style directives and markup rendering.
//!
//! Style directives are space-separated words such as `bold`, `red`,
//! `bright_blue`, `bg:green`, `rgb(1,2,3)` or `#ff00aa`. Markup strings may
//! contain `<directives>` opening tags and `</>` closing tags.

use colored::{Color, Colorize};
use std::str::FromStr;
use unicode_segmentation::UnicodeSegmentation;

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Sty {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reversed: bool,
    pub hidden: bool,
    pub strikethrough: bool,
}

fn brighten(c: Color) -> Option<Color> {
    use Color::*;
    Some(match c {
        Black => BrightBlack,
        Red => BrightRed,
        Green => BrightGreen,
        Yellow => BrightYellow,
        Blue => BrightBlue,
        Magenta => BrightMagenta,
        Cyan => BrightCyan,
        White => BrightWhite,
        other => other,
    })
}

fn parse_rgb(s: &str) -> Option<Color> {
    let inner = s.strip_prefix("rgb(")?.strip_suffix(')')?;
    let parts: Vec<&str> = inner.split(',').collect();
    if parts.len() != 3 {
        return None;
    }
    let r = parts[0].parse::<u8>().ok()?;
    let g = parts[1].parse::<u8>().ok()?;
    let b = parts[2].parse::<u8>().ok()?;
    Some(Color::TrueColor { r, g, b })
}

pub fn parse_color(s: &str) -> Option<Color> {
    if let Some(c) = parse_rgb(s) {
        return Some(c);
    }
    if let Some(rest) = s.strip_prefix("bright_") {
        return Color::from_str(rest).ok().and_then(brighten);
    }
    Color::from_str(s).ok()
}

impl Sty {
    pub fn apply_token(&mut self, tok: &str) {
        match tok {
            "clear" => *self = Sty::default(),
            "bold" => self.bold = true,
            "dimmed" => self.dimmed = true,
            "italic" => self.italic = true,
            "underline" => self.underline = true,
            "blink" => self.blink = true,
            "reversed" => self.reversed = true,
            "hidden" => self.hidden = true,
            "strikethrough" => self.strikethrough = true,
            _ => {
                if let Some(rest) = tok.strip_prefix("bg:") {
                    if let Some(c) = parse_color(rest) {
                        self.bg = Some(c);
                    }
                } else if let Some(c) = parse_color(tok) {
                    self.fg = Some(c);
                }
            }
        }
    }

    pub fn apply(&mut self, directives: &str) {
        for tok in directives.split(' ') {
            self.apply_token(tok);
        }
    }

    pub fn paint(&self, text: &str) -> String {
        if self.hidden {
            return String::new();
        }
        let mut cs = text.normal();
        if let Some(c) = self.fg {
            cs = cs.color(c);
        }
        if let Some(c) = self.bg {
            cs = cs.on_color(c);
        }
        if self.bold {
            cs = cs.bold();
        }
        if self.dimmed {
            cs = cs.dimmed();
        }
        if self.italic {
            cs = cs.italic();
        }
        if self.underline {
            cs = cs.underline();
        }
        if self.blink {
            cs = cs.blink();
        }
        if self.reversed {
            cs = cs.reversed();
        }
        if self.strikethrough {
            cs = cs.strikethrough();
        }
        cs.to_string()
    }
}

/// Check whether a style directive string results in hidden text.
pub fn is_hidden(directives: &str) -> bool {
    let mut s = Sty::default();
    s.apply(directives);
    s.hidden
}

/// Remove `italic` and `underline` directives (used for icons).
pub fn icon_directives(directives: &str) -> String {
    directives
        .split(' ')
        .filter(|t| *t != "italic" && *t != "underline")
        .collect::<Vec<_>>()
        .join(" ")
}

enum Piece<'a> {
    Text(&'a str),
    Open(&'a str),
    Close,
}

fn tokenize(markup: &str) -> Vec<Piece<'_>> {
    let mut pieces = Vec::new();
    let mut rest = markup;
    loop {
        match rest.find('<') {
            None => {
                if !rest.is_empty() {
                    pieces.push(Piece::Text(rest));
                }
                break;
            }
            Some(i) => {
                if i > 0 {
                    pieces.push(Piece::Text(&rest[..i]));
                }
                let after = &rest[i + 1..];
                match after.find('>') {
                    None => break,
                    Some(j) => {
                        let content = &after[..j];
                        if content == "/" {
                            pieces.push(Piece::Close);
                        } else {
                            pieces.push(Piece::Open(content));
                        }
                        rest = &after[j + 1..];
                    }
                }
            }
        }
    }
    pieces
}

/// Render a markup string into a terminal string.
pub fn render(markup: &str) -> String {
    let mut out = String::new();
    let mut stack: Vec<&str> = Vec::new();
    for piece in tokenize(markup) {
        match piece {
            Piece::Text(t) => {
                let mut sty = Sty::default();
                for d in &stack {
                    sty.apply(d);
                }
                out.push_str(&sty.paint(t));
            }
            Piece::Open(d) => stack.push(d),
            Piece::Close => {
                stack.pop();
            }
        }
    }
    out
}

/// Compute the visible text of a markup string (no escape codes).
pub fn plain(markup: &str) -> String {
    let mut out = String::new();
    let mut stack: Vec<&str> = Vec::new();
    for piece in tokenize(markup) {
        match piece {
            Piece::Text(t) => {
                let mut sty = Sty::default();
                for d in &stack {
                    sty.apply(d);
                }
                if !sty.hidden {
                    out.push_str(t);
                }
            }
            Piece::Open(d) => stack.push(d),
            Piece::Close => {
                stack.pop();
            }
        }
    }
    out
}

/// Visible width of a markup string, counted in grapheme clusters.
pub fn width(markup: &str) -> usize {
    plain(markup).graphemes(true).count()
}

/// Visible width of a plain string, counted in grapheme clusters.
pub fn plain_width(s: &str) -> usize {
    s.graphemes(true).count()
}

/// Wrap text in a style tag.
pub fn wrap(directives: &str, text: &str) -> String {
    format!("<{}>{}</>", directives, text)
}
