//! Configuration loading, merging and extraction.

use regex::Regex;
use std::collections::{BTreeMap, HashMap};
use std::path::{Component, Path, PathBuf};
use std::rc::Rc;

use crate::enums::{DetailField, Typ};

const DEFAULTS_YAML: &str = include_str!("defaults.yml");
const CONF_FILE: &str = ".pls.yml";

// ---------------------------------------------------------------------------
// Tagged values
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub enum V {
    Str(String),
    U(u64),
    I(i64),
    F(f64),
    Bool(bool),
    Unit,
    Seq(Vec<TV>),
    Map(BTreeMap<String, TV>),
}

#[derive(Clone, Debug)]
pub struct TV {
    pub v: V,
    pub tag: usize,
}

fn key_string(k: &serde_yaml::Value) -> String {
    match k {
        serde_yaml::Value::String(s) => s.clone(),
        serde_yaml::Value::Number(n) => n.to_string(),
        serde_yaml::Value::Bool(b) => b.to_string(),
        serde_yaml::Value::Null => "null".to_string(),
        serde_yaml::Value::Tagged(t) => key_string(&t.value),
        other => format!("{:?}", other),
    }
}

fn from_yaml(y: &serde_yaml::Value, tag: usize) -> TV {
    let v = match y {
        serde_yaml::Value::Null => V::Unit,
        serde_yaml::Value::Bool(b) => V::Bool(*b),
        serde_yaml::Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                V::U(u)
            } else if let Some(i) = n.as_i64() {
                V::I(i)
            } else {
                V::F(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_yaml::Value::String(s) => V::Str(s.clone()),
        serde_yaml::Value::Sequence(seq) => V::Seq(seq.iter().map(|e| from_yaml(e, tag)).collect()),
        serde_yaml::Value::Mapping(m) => {
            let mut out = BTreeMap::new();
            for (k, val) in m {
                out.insert(key_string(k), from_yaml(val, tag));
            }
            V::Map(out)
        }
        serde_yaml::Value::Tagged(t) => return from_yaml(&t.value, tag),
    };
    TV { v, tag }
}

/// Merge `incoming` into `base`, concatenating sequences and merging maps.
fn admerge(base: &mut TV, incoming: TV) {
    match (&mut base.v, incoming.v) {
        (V::Map(a), V::Map(b)) => {
            for (k, v) in b {
                match a.get_mut(&k) {
                    Some(existing) => admerge(existing, v),
                    None => {
                        a.insert(k, v);
                    }
                }
            }
        }
        (V::Seq(a), V::Seq(b)) => {
            a.extend(b);
        }
        (_, other) => {
            base.v = other;
            base.tag = incoming.tag;
        }
    }
}

// ---------------------------------------------------------------------------
// Error construction
// ---------------------------------------------------------------------------

fn actual(v: &V) -> String {
    match v {
        V::Str(s) => format!("string {:?}", s),
        V::U(n) => format!("unsigned int `{}`", n),
        V::I(n) => format!("signed int `{}`", n),
        V::F(f) => format!("float `{}`", f),
        V::Bool(b) => format!("bool {}", b),
        V::Unit => "unit".to_string(),
        V::Seq(_) => "sequence".to_string(),
        V::Map(_) => "map".to_string(),
    }
}

fn one_of(names: &[&str]) -> String {
    match names.len() {
        0 => "none".to_string(),
        1 => format!("`{}`", names[0]),
        2 => format!("`{}` or `{}`", names[0], names[1]),
        _ => {
            let parts: Vec<String> = names.iter().map(|n| format!("`{}`", n)).collect();
            format!("one of {}", parts.join(", "))
        }
    }
}

#[derive(Debug, Clone)]
struct ExErr {
    kind: String,
    path: Vec<String>,
    tag: usize,
}

type ExResult<T> = Result<T, ExErr>;

fn invalid_type(tv: &TV, path: &[String], expected: &str) -> ExErr {
    ExErr {
        kind: format!("invalid type: found {}, expected {}", actual(&tv.v), expected),
        path: path.to_vec(),
        tag: tv.tag,
    }
}

fn push(path: &[String], seg: &str) -> Vec<String> {
    let mut p = path.to_vec();
    p.push(seg.to_string());
    p
}

// ---------------------------------------------------------------------------
// Primitive extractors
// ---------------------------------------------------------------------------

fn ex_str(tv: &TV, path: &[String]) -> ExResult<String> {
    match &tv.v {
        V::Str(s) => Ok(s.clone()),
        _ => Err(invalid_type(tv, path, "a string")),
    }
}

fn ex_opt<T>(tv: &TV, path: &[String], f: impl Fn(&TV, &[String]) -> ExResult<T>) -> ExResult<Option<T>> {
    match &tv.v {
        V::Unit => Ok(None),
        _ => f(tv, path).map(Some),
    }
}

fn ex_i8(tv: &TV, path: &[String]) -> ExResult<i8> {
    match &tv.v {
        V::U(n) => {
            if *n <= i8::MAX as u64 {
                Ok(*n as i8)
            } else {
                Err(ExErr {
                    kind: format!("invalid value {}, expected i8", actual(&tv.v)),
                    path: path.to_vec(),
                    tag: tv.tag,
                })
            }
        }
        V::I(n) => {
            if *n >= i8::MIN as i64 && *n <= i8::MAX as i64 {
                Ok(*n as i8)
            } else {
                Err(ExErr {
                    kind: format!("invalid value {}, expected i8", actual(&tv.v)),
                    path: path.to_vec(),
                    tag: tv.tag,
                })
            }
        }
        _ => Err(invalid_type(tv, path, "i8")),
    }
}

fn ex_seq<T>(tv: &TV, path: &[String], f: impl Fn(&TV, &[String]) -> ExResult<T>) -> ExResult<Vec<T>> {
    match &tv.v {
        V::Seq(items) => {
            let mut out = Vec::with_capacity(items.len());
            for (i, item) in items.iter().enumerate() {
                out.push(f(item, &push(path, &i.to_string()))?);
            }
            Ok(out)
        }
        _ => Err(invalid_type(tv, path, "a sequence")),
    }
}

fn ex_map<T>(tv: &TV, path: &[String], f: impl Fn(&TV, &[String]) -> ExResult<T>) -> ExResult<Vec<(String, T)>> {
    match &tv.v {
        V::Map(m) => {
            let mut out = Vec::with_capacity(m.len());
            for (k, v) in m {
                out.push((k.clone(), f(v, &push(path, k))?));
            }
            Ok(out)
        }
        _ => Err(invalid_type(tv, path, "a map")),
    }
}

fn ex_enum_map<T>(
    tv: &TV,
    path: &[String],
    variants: &[&str],
    f: impl Fn(&TV, &[String]) -> ExResult<T>,
) -> ExResult<Vec<(String, T)>> {
    match &tv.v {
        V::Map(m) => {
            let mut out = Vec::with_capacity(m.len());
            for (k, v) in m {
                let p = push(path, k);
                if !variants.contains(&k.as_str()) {
                    return Err(ExErr {
                        kind: format!("unknown variant: found `{}`, expected `{}`", k, one_of(variants)),
                        path: p,
                        tag: v.tag,
                    });
                }
                out.push((k.clone(), f(v, &p)?));
            }
            Ok(out)
        }
        _ => Err(invalid_type(tv, path, "a map")),
    }
}

/// Extract a struct, either from a map (by field name) or from a sequence
/// (by field position). The callback receives the field index and value.
fn ex_struct(
    tv: &TV,
    path: &[String],
    name: &str,
    fields: &[&str],
    mut f: impl FnMut(usize, &TV, &[String]) -> ExResult<()>,
) -> ExResult<()> {
    match &tv.v {
        V::Map(m) => {
            for (k, v) in m {
                if let Some(idx) = fields.iter().position(|x| x == k) {
                    f(idx, v, &push(path, k))?;
                }
            }
            Ok(())
        }
        V::Seq(items) => {
            if items.len() < fields.len() {
                return Err(ExErr {
                    kind: format!(
                        "invalid length {}, expected struct {} with {} elements",
                        items.len(),
                        name,
                        fields.len()
                    ),
                    path: path.to_vec(),
                    tag: tv.tag,
                });
            }
            for (i, item) in items.iter().take(fields.len()).enumerate() {
                f(i, item, &push(path, &i.to_string()))?;
            }
            Ok(())
        }
        _ => Err(invalid_type(tv, path, &format!("struct {}", name))),
    }
}

