    pub imp_styles: Vec<(i8, String)>,
    pub tree: [String; 4],
    // entry_const
    pub dev_style: String,
    pub ino_style: String,
    pub nlink_styles: [String; 4],
    pub typ: HashMap<String, TypInfo>,
    pub perm_styles: HashMap<String, String>,
    pub oct_styles: HashMap<String, String>,
    pub user_styles: OwnerStyles,
    pub group_styles: OwnerStyles,
