/// Compute a relative path from `base` to `path` (both absolute).
pub fn diff_paths(path: &Path, base: &Path) -> Option<PathBuf> {
    if path.is_absolute() != base.is_absolute() {
        if path.is_absolute() {
            return Some(path.to_path_buf());
        }
        return None;
    }
    let mut ita = path.components();
    let mut itb = base.components();
    let mut comps: Vec<Component> = Vec::new();
    loop {
        match (ita.next(), itb.next()) {
            (None, None) => break,
            (Some(a), None) => {
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
            (None, _) => comps.push(Component::ParentDir),
            (Some(a), Some(b)) if comps.is_empty() && a == b => {}
            (Some(a), Some(Component::CurDir)) => comps.push(a),
            (Some(_), Some(Component::ParentDir)) => return None,
            (Some(a), Some(_)) => {
                comps.push(Component::ParentDir);
                for _ in itb.by_ref() {
                    comps.push(Component::ParentDir);
                }
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
        }
    }
    Some(comps.iter().map(|c| c.as_os_str()).collect())
}

fn display_source(p: &Path) -> String {
    if let Ok(cwd) = std::env::current_dir() {
        if let Some(r) = diff_paths(p, &cwd) {
            if r.iter().count() < p.iter().count() {
                return r.display().to_string();
            }
        }
    }
    p.display().to_string()
}

/// Lexically normalise an absolute path (resolving `.` and `..`).
pub fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                if !out.pop() {
                    // stay at root
                }
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

fn find_git_root(start: &Path) -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    let abs = normalize(&cwd.join(start));
    let mut cur: Option<&Path> = Some(abs.as_path());
    while let Some(dir) = cur {
        if dir.join(".git").exists() {
            return Some(dir.to_path_buf());
        }
        cur = dir.parent();
    }
    None
}

// ---------------------------------------------------------------------------
// Conf manager
// ---------------------------------------------------------------------------

pub struct ConfMan {
    base: TV,
    sources: Vec<PathBuf>,
    cache: HashMap<Vec<PathBuf>, Result<Rc<Conf>, String>>,
}

impl ConfMan {
    pub fn new() -> ConfMan {
        let defaults: serde_yaml::Value =
            serde_yaml::from_str(DEFAULTS_YAML).expect("default configuration is valid");
        ConfMan {
            base: from_yaml(&defaults, 0),
            sources: vec![PathBuf::new()],
            cache: HashMap::new(),
        }
    }

    fn conf_files(&self, base: &Path) -> Vec<PathBuf> {
        let mut files = Vec::new();
        if let Some(home) = std::env::var_os("HOME") {
            if !home.is_empty() {
                files.push(PathBuf::from(home).join(CONF_FILE));
            }
        }
        match find_git_root(base) {
            Some(root) => {
                let mut dirs: Vec<&Path> = Vec::new();
                for anc in base.ancestors() {
                    dirs.push(anc);
                    if anc == root.as_path() {
                        break;
                    }
                }
                for d in dirs.iter().rev() {
                    files.push(d.join(CONF_FILE));
                }
            }
            None => files.push(base.join(CONF_FILE)),
        }
        files
    }

    /// Get the configuration applicable to the given directory.
    pub fn get(&mut self, base: &Path) -> Result<Rc<Conf>, String> {
        let files = self.conf_files(base);
        if let Some(r) = self.cache.get(&files) {
            return r.clone();
        }
        let result = self.build(&files);
        self.cache.insert(files, result.clone());
        result
    }

    fn build(&mut self, files: &[PathBuf]) -> Result<Rc<Conf>, String> {
        let cwd = std::env::current_dir().unwrap_or_default();
        let mut merged = self.base.clone();
        let mut errors: Vec<String> = Vec::new();
        for f in files {
            let abs = if f.is_absolute() { f.clone() } else { cwd.join(f) };
            if !abs.is_file() {
                continue;
            }
            let src_display = display_source(&abs);
            let content = match std::fs::read_to_string(&abs) {
                Ok(c) => c,
                Err(e) => {
                    errors.push(format!("{} in {} YAML file", e, src_display));
                    continue;
                }
            };
            let parsed: Result<BTreeMap<String, serde_yaml::Value>, _> = serde_yaml::from_str(&content);
            match parsed {
                Ok(map) => {
                    let tag = self.sources.len();
                    self.sources.push(abs.clone());
                    let mut m = BTreeMap::new();
                    for (k, v) in map {
                        m.insert(k, from_yaml(&v, tag));
                    }
                    if errors.is_empty() {
                        admerge(&mut merged, TV { v: V::Map(m), tag });
                    }
                }
                Err(e) => errors.push(format!("{} in {} YAML file", e, src_display)),
            }
        }
        if !errors.is_empty() {
            let mut msg = errors[0].clone();
            if errors.len() > 1 {
                msg.push('\n');
                msg.push_str(errors.last().unwrap());
            }
            return Err(msg);
        }
        match extract(&merged) {
            Ok(c) => Ok(Rc::new(c)),
            Err(e) => {
                let mut msg = e.kind.clone();
                if !e.path.is_empty() {
                    msg.push_str(&format!(" for key \"default.{}\"", e.path.join(".")));
                }
                if e.tag > 0 {
                    msg.push_str(&format!(" in {} YAML file", display_source(&self.sources[e.tag])));
                } else {
                    msg.push_str(" in Serialized defaults");
                }
                Err(msg)
            }
        }
    }
}
