cd /workspace && cat > src/config.rs <<'EOF'
//! Configuration loading, merging and extraction.

use regex::Regex;
use std::collections::{BTreeMap, HashMap};
use std::path::{Component, Path, PathBuf};
use std::rc::Rc;

use crate::enums::{DetailField, Typ};

const DEFAULTS_YAML: &str = include_str!("defaults.yml");
const CONF_FILE: &str = ".pls.yml";

// ---------------------------------------------------------------------------
// Tagged values
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub enum V {
    Str(String),
    U(u64),
    I(i64),
    F(f64),
    Bool(bool),
    Unit,
    Seq(Vec<TV>),
    Map(BTreeMap<String, TV>),
}

#[derive(Clone, Debug)]
pub struct TV {
    pub v: V,
    pub tag: usize,
}

fn key_string(k: &serde_yaml::Value) -> String {
    match k {
        serde_yaml::Value::String(s) => s.clone(),
        serde_yaml::Value::Number(n) => n.to_string(),
        serde_yaml::Value::Bool(b) => b.to_string(),
        serde_yaml::Value::Null => "null".to_string(),
        serde_yaml::Value::Tagged(t) => key_string(&t.value),
        other => format!("{:?}", other),
    }
}

fn from_yaml(y: &serde_yaml::Value, tag: usize) -> TV {
    let v = match y {
        serde_yaml::Value::Null => V::Unit,
        serde_yaml::Value::Bool(b) => V::Bool(*b),
        serde_yaml::Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                V::U(u)
            } else if let Some(i) = n.as_i64() {
                V::I(i)
            } else {
                V::F(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_yaml::Value::String(s) => V::Str(s.clone()),
        serde_yaml::Value::Sequence(seq) => V::Seq(seq.iter().map(|e| from_yaml(e, tag)).collect()),
        serde_yaml::Value::Mapping(m) => {
            let mut out = BTreeMap::new();
            for (k, val) in m {
                out.insert(key_string(k), from_yaml(val, tag));
            }
            V::Map(out)
        }
        serde_yaml::Value::Tagged(t) => return from_yaml(&t.value, tag),
    };
    TV { v, tag }
}

/// Merge `incoming` into `base`, concatenating sequences and merging maps.
fn admerge(base: &mut TV, incoming: TV) {
    match (&mut base.v, incoming.v) {
        (V::Map(a), V::Map(b)) => {
            for (k, v) in b {
                match a.get_mut(&k) {
                    Some(existing) => admerge(existing, v),
                    None => {
                        a.insert(k, v);
                    }
                }
            }
        }
        (V::Seq(a), V::Seq(b)) => {
            a.extend(b);
        }
        (_, other) => {
            base.v = other;
            base.tag = incoming.tag;
        }
    }
}

// ---------------------------------------------------------------------------
// Error construction
// ---------------------------------------------------------------------------

fn actual(v: &V) -> String {
    match v {
        V::Str(s) => format!("string {:?}", s),
        V::U(n) => format!("unsigned int `{}`", n),
        V::I(n) => format!("signed int `{}`", n),
        V::F(f) => format!("float `{}`", f),
        V::Bool(b) => format!("bool {}", b),
        V::Unit => "unit".to_string(),
        V::Seq(_) => "sequence".to_string(),
        V::Map(_) => "map".to_string(),
    }
}

fn one_of(names: &[&str]) -> String {
    match names.len() {
        0 => "none".to_string(),
        1 => format!("`{}`", names[0]),
        2 => format!("`{}` or `{}`", names[0], names[1]),
        _ => {
            let parts: Vec<String> = names.iter().map(|n| format!("`{}`", n)).collect();
            format!("one of {}", parts.join(", "))
        }
    }
}

#[derive(Debug, Clone)]
struct ExErr {
    kind: String,
    path: Vec<String>,
    tag: usize,
}

type ExResult<T> = Result<T, ExErr>;

fn invalid_type(tv: &TV, path: &[String], expected: &str) -> ExErr {
    ExErr {
        kind: format!("invalid type: found {}, expected {}", actual(&tv.v), expected),
        path: path.to_vec(),
        tag: tv.tag,
    }
}

fn push(path: &[String], seg: &str) -> Vec<String> {
    let mut p = path.to_vec();
    p.push(seg.to_string());
    p
}

// ---------------------------------------------------------------------------
// Primitive extractors
// ---------------------------------------------------------------------------

fn ex_str(tv: &TV, path: &[String]) -> ExResult<String> {
    match &tv.v {
        V::Str(s) => Ok(s.clone()),
        _ => Err(invalid_type(tv, path, "a string")),
    }
}

fn ex_opt<T>(tv: &TV, path: &[String], f: impl Fn(&TV, &[String]) -> ExResult<T>) -> ExResult<Option<T>> {
    match &tv.v {
        V::Unit => Ok(None),
        _ => f(tv, path).map(Some),
    }
}

fn ex_i8(tv: &TV, path: &[String]) -> ExResult<i8> {
    match &tv.v {
        V::U(n) => {
            if *n <= i8::MAX as u64 {
                Ok(*n as i8)
            } else {
                Err(ExErr {
                    kind: format!("invalid value {}, expected i8", actual(&tv.v)),
                    path: path.to_vec(),
                    tag: tv.tag,
                })
            }
        }
        V::I(n) => {
            if *n >= i8::MIN as i64 && *n <= i8::MAX as i64 {
                Ok(*n as i8)
            } else {
                Err(ExErr {
                    kind: format!("invalid value {}, expected i8", actual(&tv.v)),
                    path: path.to_vec(),
                    tag: tv.tag,
                })
            }
        }
        _ => Err(invalid_type(tv, path, "i8")),
    }
}

fn ex_seq<T>(tv: &TV, path: &[String], f: impl Fn(&TV, &[String]) -> ExResult<T>) -> ExResult<Vec<T>> {
    match &tv.v {
        V::Seq(items) => {
            let mut out = Vec::with_capacity(items.len());
            for (i, item) in items.iter().enumerate() {
                out.push(f(item, &push(path, &i.to_string()))?);
            }
            Ok(out)
        }
        _ => Err(invalid_type(tv, path, "a sequence")),
    }
}

fn ex_map<T>(tv: &TV, path: &[String], f: impl Fn(&TV, &[String]) -> ExResult<T>) -> ExResult<Vec<(String, T)>> {
    match &tv.v {
        V::Map(m) => {
            let mut out = Vec::with_capacity(m.len());
            for (k, v) in m {
                out.push((k.clone(), f(v, &push(path, k))?));
            }
            Ok(out)
        }
        _ => Err(invalid_type(tv, path, "a map")),
    }
}

fn ex_enum_map<T>(
    tv: &TV,
    path: &[String],
    variants: &[&str],
    f: impl Fn(&TV, &[String]) -> ExResult<T>,
) -> ExResult<Vec<(String, T)>> {
    match &tv.v {
        V::Map(m) => {
            let mut out = Vec::with_capacity(m.len());
            for (k, v) in m {
                let p = push(path, k);
                if !variants.contains(&k.as_str()) {
                    return Err(ExErr {
                        kind: format!("unknown variant: found `{}`, expected `{}`", k, one_of(variants)),
                        path: p,
                        tag: v.tag,
                    });
                }
                out.push((k.clone(), f(v, &p)?));
            }
            Ok(out)
        }
        _ => Err(invalid_type(tv, path, "a map")),
    }
}

/// Extract a struct, either from a map (by field name) or from a sequence
/// (by field position). The callback receives the field index and value.
fn ex_struct(
    tv: &TV,
    path: &[String],
    name: &str,
    fields: &[&str],
    mut f: impl FnMut(usize, &TV, &[String]) -> ExResult<()>,
) -> ExResult<()> {
    match &tv.v {
        V::Map(m) => {
            for (k, v) in m {
                if let Some(idx) = fields.iter().position(|x| x == k) {
                    f(idx, v, &push(path, k))?;
                }
            }
            Ok(())
        }
        V::Seq(items) => {
            if items.len() < fields.len() {
                return Err(ExErr {
                    kind: format!(
                        "invalid length {}, expected struct {} with {} elements",
                        items.len(),
                        name,
                        fields.len()
                    ),
                    path: path.to_vec(),
                    tag: tv.tag,
                });
            }
            for (i, item) in items.iter().take(fields.len()).enumerate() {
                f(i, item, &push(path, &i.to_string()))?;
            }
            Ok(())
        }
        _ => Err(invalid_type(tv, path, &format!("struct {}", name))),
    }
}

// ---------------------------------------------------------------------------
// Typed configuration
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub enum Collapse {
    Name(String),
    Ext(String),
}

#[derive(Debug, Clone)]
pub struct Spec {
    pub pattern: Regex,
    pub icons: Option<Vec<String>>,
    pub style: Option<String>,
    pub importance: Option<i8>,
    pub collapse: Option<Collapse>,
}

#[derive(Debug, Clone, Default)]
pub struct TypInfo {
    pub ch: String,
    pub suffix: String,
    pub icons: Vec<String>,
    pub style: String,
}

#[derive(Debug, Clone, Default)]
pub struct SymlinkInfo {
    pub sep: String,
    pub style: String,
}

#[derive(Debug, Clone, Default)]
pub struct OwnerStyles {
    pub curr: String,
    pub other: String,
}

#[derive(Debug, Clone)]
pub struct Conf {
    pub icons: HashMap<String, String>,
    pub specs: Vec<Spec>,
    // app_const
    pub column_names: HashMap<String, String>,
    pub header_style: String,
    pub imp_styles: Vec<(i8, String)>,
    pub tree: [String; 4],
    // entry_const
    pub dev_style: String,
    pub ino_style: String,
    pub nlink_styles: [String; 4],
    pub typ: HashMap<String, TypInfo>,
    pub perm_styles: HashMap<String, String>,
    pub oct_styles: HashMap<String, String>,
    pub user_styles: OwnerStyles,
    pub group_styles: OwnerStyles,
    pub size_styles: [String; 3],
    pub blocks_style: String,
    pub timestamp_formats: HashMap<String, String>,
    pub symlink: HashMap<String, SymlinkInfo>,
}

impl Conf {
    fn empty() -> Conf {
        Conf {
            icons: HashMap::new(),
            specs: Vec::new(),
            column_names: HashMap::new(),
            header_style: String::new(),
            imp_styles: Vec::new(),
            tree: Default::default(),
            dev_style: String::new(),
            ino_style: String::new(),
            nlink_styles: Default::default(),
            typ: HashMap::new(),
            perm_styles: HashMap::new(),
            oct_styles: HashMap::new(),
            user_styles: OwnerStyles::default(),
            group_styles: OwnerStyles::default(),
            size_styles: Default::default(),
            blocks_style: String::new(),
            timestamp_formats: HashMap::new(),
            symlink: HashMap::new(),
        }
    }

    pub fn typ_info(&self, typ: Typ) -> TypInfo {
        self.typ.get(typ.conf_key()).cloned().unwrap_or_default()
    }

    pub fn column_name(&self, f: DetailField) -> String {
        self.column_names.get(f.key()).cloned().unwrap_or_default()
    }
}

const PERM_KEYS: &[&str] = &["none", "read", "write", "execute", "special"];
const OCT_KEYS: &[&str] = &["special", "user", "group", "other"];
const SYM_KEYS: &[&str] = &["ok", "broken", "cyclic", "error"];

fn ex_spec(tv: &TV, path: &[String]) -> ExResult<Spec> {
    let fields = ["pattern", "icons", "style", "importance", "collapse"];
    let mut pattern: Option<Regex> = None;
    let mut icons = None;
    let mut style = None;
    let mut importance = None;
    let mut collapse = None;
    ex_struct(tv, path, "Spec", &fields, |idx, v, p| {
        match idx {
            0 => {
                let s = ex_str(v, p)?;
                match Regex::new(&s) {
                    Ok(r) => pattern = Some(r),
                    Err(e) => {
                        return Err(ExErr {
                            kind: e.to_string(),
                            path: p.to_vec(),
                            tag: v.tag,
                        })
                    }
                }
            }
            1 => icons = ex_opt(v, p, |v, p| ex_seq(v, p, ex_str))?,
            2 => style = ex_opt(v, p, ex_str)?,
            3 => importance = ex_opt(v, p, ex_i8)?,
            4 => collapse = ex_opt(v, p, ex_collapse)?,
            _ => {}
        }
        Ok(())
    })?;
    match pattern {
        Some(pattern) => Ok(Spec {
            pattern,
            icons,
            style,
            importance,
            collapse,
        }),
        None => Err(ExErr {
            kind: "missing field `pattern`".to_string(),
            path: path.to_vec(),
            tag: tv.tag,
        }),
    }
}

fn ex_collapse(tv: &TV, path: &[String]) -> ExResult<Collapse> {
    let variants = ["name", "ext"];
    match &tv.v {
        V::Str(s) => Err(ExErr {
            kind: if variants.contains(&s.as_str()) {
                "invalid type: unit variant, expected newtype variant".to_string()
            } else {
                format!("unknown variant: found `{}`, expected `{}`", s, one_of(&variants))
            },
            path: path.to_vec(),
            tag: tv.tag,
        }),
        V::Map(m) => match m.iter().next() {
            None => Err(invalid_type(tv, path, "enum")),
            Some((k, v)) => {
                let p = push(path, k);
                match k.as_str() {
                    "name" => Ok(Collapse::Name(ex_str(v, &p)?)),
                    "ext" => Ok(Collapse::Ext(ex_str(v, &p)?)),
                    _ => Err(ExErr {
                        kind: format!("unknown variant: found `{}`, expected `{}`", k, one_of(&variants)),
                        path: p,
                        tag: v.tag,
                    }),
                }
            }
        },
        _ => Err(invalid_type(tv, path, "enum Collapse")),
    }
}

fn ex_imp_style(tv: &TV, path: &[String]) -> ExResult<(i8, String)> {
    match &tv.v {
        V::Seq(items) => {
            if items.len() < 2 {
                return Err(ExErr {
                    kind: format!("invalid length {}, expected a tuple of size 2", items.len()),
                    path: path.to_vec(),
                    tag: tv.tag,
                });
            }
            let a = ex_i8(&items[0], &push(path, "0"))?;
            let b = ex_str(&items[1], &push(path, "1"))?;
            Ok((a, b))
        }
        _ => Err(invalid_type(tv, path, "a tuple of size 2")),
    }
}

fn ex_owner_styles(tv: &TV, path: &[String], out: &mut OwnerStyles) -> ExResult<()> {
    ex_struct(tv, path, "OwnerStyles", &["curr", "other"], |idx, v, p| {
        let s = ex_str(v, p)?;
        if idx == 0 {
            out.curr = s;
        } else {
            out.other = s;
        }
        Ok(())
    })
}

fn ex_app_const(tv: &TV, path: &[String], conf: &mut Conf) -> ExResult<()> {
    let fields = ["table", "imp_styles", "tree"];
    ex_struct(tv, path, "AppConst", &fields, |idx, v, p| {
        match idx {
            0 => ex_struct(v, p, "TableInfo", &["column_names", "header_style"], |idx, v, p| {
                match idx {
                    0 => {
                        for (k, s) in ex_enum_map(v, p, DetailField::CONF_KEYS, ex_str)? {
                            conf.column_names.insert(k, s);
                        }
                    }
                    _ => conf.header_style = ex_str(v, p)?,
                }
                Ok(())
            })?,
            1 => conf.imp_styles = ex_seq(v, p, ex_imp_style)?,
            _ => ex_struct(v, p, "TreeInfo", &["0", "1", "2", "3"], |idx, v, p| {
                conf.tree[idx] = ex_str(v, p)?;
                Ok(())
            })?,
        }
        Ok(())
    })
}

fn ex_entry_const(tv: &TV, path: &[String], conf: &mut Conf) -> ExResult<()> {
    let fields = [
        "dev_style",
        "ino_style",
        "nlink_styles",
        "typ",
        "perm_styles",
        "oct_styles",
        "user_styles",
        "group_styles",
        "size_styles",
        "blocks_style",
        "timestamp_formats",
        "symlink",
    ];
    ex_struct(tv, path, "EntryConst", &fields, |idx, v, p| {
        match idx {
            0 => conf.dev_style = ex_str(v, p)?,
            1 => conf.ino_style = ex_str(v, p)?,
            2 => ex_struct(
                v,
                p,
                "NlinkStyles",
                &["file_sing", "file_plur", "dir_sing", "dir_plur"],
                |idx, v, p| {
                    conf.nlink_styles[idx] = ex_str(v, p)?;
                    Ok(())
                },
            )?,
            3 => {
                for (k, info) in ex_enum_map(v, p, Typ::CONF_KEYS, |v, p| {
                    let mut info = TypInfo::default();
                    ex_struct(v, p, "TypInfo", &["ch", "suffix", "icons", "style"], |idx, v, p| {
                        match idx {
                            0 => info.ch = ex_str(v, p)?,
                            1 => info.suffix = ex_str(v, p)?,
                            2 => info.icons = ex_seq(v, p, ex_str)?,
                            _ => info.style = ex_str(v, p)?,
                        }
                        Ok(())
                    })?;
                    Ok(info)
                })? {
                    conf.typ.insert(k, info);
                }
            }
            4 => {
                for (k, s) in ex_enum_map(v, p, PERM_KEYS, ex_str)? {
                    conf.perm_styles.insert(k, s);
                }
            }
            5 => {
                for (k, s) in ex_enum_map(v, p, OCT_KEYS, ex_str)? {
                    conf.oct_styles.insert(k, s);
                }
            }
            6 => ex_owner_styles(v, p, &mut conf.user_styles)?,
            7 => ex_owner_styles(v, p, &mut conf.group_styles)?,
            8 => ex_struct(v, p, "SizeStyles", &["mag", "prefix", "base"], |idx, v, p| {
                conf.size_styles[idx] = ex_str(v, p)?;
                Ok(())
            })?,
            9 => conf.blocks_style = ex_str(v, p)?,
            10 => {
                for (k, s) in ex_enum_map(v, p, DetailField::CONF_KEYS, ex_str)? {
                    conf.timestamp_formats.insert(k, s);
                }
            }
            _ => {
                for (k, info) in ex_enum_map(v, p, SYM_KEYS, |v, p| {
                    let mut info = SymlinkInfo::default();
                    ex_struct(v, p, "SymlinkInfo", &["sep", "style"], |idx, v, p| {
                        if idx == 0 {
                            info.sep = ex_str(v, p)?;
                        } else {
                            info.style = ex_str(v, p)?;
                        }
                        Ok(())
                    })?;
                    Ok(info)
                })? {
                    conf.symlink.insert(k, info);
                }
            }
        }
        Ok(())
    })
}

fn extract(tv: &TV) -> ExResult<Conf> {
    let mut conf = Conf::empty();
    let path: Vec<String> = Vec::new();
    match &tv.v {
        V::Map(m) => {
            for (k, v) in m {
                let p = push(&path, k);
                match k.as_str() {
                    "app_const" => ex_app_const(v, &p, &mut conf)?,
                    "entry_const" => ex_entry_const(v, &p, &mut conf)?,
                    "icons" => {
                        for (k, s) in ex_map(v, &p, ex_str)? {
                            conf.icons.insert(k, s);
                        }
                    }
                    "specs" => conf.specs = ex_seq(v, &p, ex_spec)?,
                    _ => {}
                }
            }
            Ok(conf)
        }
        _ => Err(invalid_type(tv, &path, "struct Conf")),
    }
}

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------

/// Compute a relative path from `base` to `path` (both absolute).
pub fn diff_paths(path: &Path, base: &Path) -> Option<PathBuf> {
    if path.is_absolute() != base.is_absolute() {
        if path.is_absolute() {
            return Some(path.to_path_buf());
        }
        return None;
    }
    let mut ita = path.components();
    let mut itb = base.components();
    let mut comps: Vec<Component> = Vec::new();
    loop {
        match (ita.next(), itb.next()) {
            (None, None) => break,
            (Some(a), None) => {
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
            (None, _) => comps.push(Component::ParentDir),
            (Some(a), Some(b)) if comps.is_empty() && a == b => {}
            (Some(a), Some(Component::CurDir)) => comps.push(a),
            (Some(_), Some(Component::ParentDir)) => return None,
            (Some(a), Some(_)) => {
                comps.push(Component::ParentDir);
                for _ in itb.by_ref() {
                    comps.push(Component::ParentDir);
                }
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
        }
    }
    Some(comps.iter().map(|c| c.as_os_str()).collect())
}

fn display_source(p: &Path) -> String {
    if let Ok(cwd) = std::env::current_dir() {
        if let Some(r) = diff_paths(p, &cwd) {
            if r.iter().count() < p.iter().count() {
                return r.display().to_string();
            }
        }
    }
    p.display().to_string()
}

/// Lexically normalise an absolute path (resolving `.` and `..`).
pub fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                if !out.pop() {
                    // stay at root
                }
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

fn find_git_root(start: &Path) -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    let abs = normalize(&cwd.join(start));
    let mut cur: Option<&Path> = Some(abs.as_path());
    while let Some(dir) = cur {
        if dir.join(".git").exists() {
            return Some(dir.to_path_buf());
        }
        cur = dir.parent();
    }
    None
}

// ---------------------------------------------------------------------------
// Conf manager
// ---------------------------------------------------------------------------

pub struct ConfMan {
    base: TV,
    sources: Vec<PathBuf>,
    cache: HashMap<Vec<PathBuf>, Result<Rc<Conf>, String>>,
}

impl ConfMan {
    pub fn new() -> ConfMan {
        let defaults: serde_yaml::Value =
            serde_yaml::from_str(DEFAULTS_YAML).expect("default configuration is valid");
        ConfMan {
            base: from_yaml(&defaults, 0),
            sources: vec![PathBuf::new()],
            cache: HashMap::new(),
        }
    }

    fn conf_files(&self, base: &Path) -> Vec<PathBuf> {
        let mut files = Vec::new();
        if let Some(home) = std::env::var_os("HOME") {
            if !home.is_empty() {
                files.push(PathBuf::from(home).join(CONF_FILE));
            }
        }
        match find_git_root(base) {
            Some(root) => {
                let mut dirs: Vec<&Path> = Vec::new();
                for anc in base.ancestors() {
                    dirs.push(anc);
                    if anc == root.as_path() {
                        break;
                    }
                }
                for d in dirs.iter().rev() {
                    files.push(d.join(CONF_FILE));
                }
            }
            None => files.push(base.join(CONF_FILE)),
        }
        files
    }

    /// Get the configuration applicable to the given directory.
    pub fn get(&mut self, base: &Path) -> Result<Rc<Conf>, String> {
        let files = self.conf_files(base);
        if let Some(r) = self.cache.get(&files) {
            return r.clone();
        }
        let result = self.build(&files);
        self.cache.insert(files, result.clone());
        result
    }

    fn build(&mut self, files: &[PathBuf]) -> Result<Rc<Conf>, String> {
        let cwd = std::env::current_dir().unwrap_or_default();
        let mut merged = self.base.clone();
        let mut errors: Vec<String> = Vec::new();
        for f in files {
            let abs = if f.is_absolute() { f.clone() } else { cwd.join(f) };
            if !abs.is_file() {
                continue;
            }
            let src_display = display_source(&abs);
            let content = match std::fs::read_to_string(&abs) {
                Ok(c) => c,
                Err(e) => {
                    errors.push(format!("{} in {} YAML file", e, src_display));
                    continue;
                }
            };
            let parsed: Result<BTreeMap<String, serde_yaml::Value>, _> = serde_yaml::from_str(&content);
            match parsed {
                Ok(map) => {
                    let tag = self.sources.len();
                    self.sources.push(abs.clone());
                    let mut m = BTreeMap::new();
                    for (k, v) in map {
                        m.insert(k, from_yaml(&v, tag));
                    }
                    if errors.is_empty() {
                        admerge(&mut merged, TV { v: V::Map(m), tag });
                    }
                }
                Err(e) => errors.push(format!("{} in {} YAML file", e, src_display)),
            }
        }
        if !errors.is_empty() {
            let mut msg = errors[0].clone();
            if errors.len() > 1 {
                msg.push('\n');
                msg.push_str(errors.last().unwrap());
            }
            return Err(msg);
        }
        match extract(&merged) {
            Ok(c) => Ok(Rc::new(c)),
            Err(e) => {
                let mut msg = e.kind.clone();
                if !e.path.is_empty() {
                    msg.push_str(&format!(" for key \"default.{}\"", e.path.join(".")));
                }
                if e.tag > 0 {
                    msg.push_str(&format!(" in {} YAML file", display_source(&self.sources[e.tag])));
                } else {
                    msg.push_str(" in Serialized defaults");
                }
                Err(msg)
            }
        }
    }
}
