//! User and group lookups.

use std::collections::HashMap;
use std::ffi::CStr;

pub struct OwnerMan {
    users: HashMap<u32, Option<String>>,
    groups: HashMap<u32, Option<(String, Vec<String>)>>,
    curr_uid: u32,
    curr_name: Option<String>,
}

fn lookup_user(uid: u32) -> Option<String> {
    unsafe {
        let mut buf = vec![0 as libc::c_char; 16384];
        let mut pwd: libc::passwd = std::mem::zeroed();
        let mut result: *mut libc::passwd = std::ptr::null_mut();
        let rc = libc::getpwuid_r(uid, &mut pwd, buf.as_mut_ptr(), buf.len(), &mut result);
        if rc != 0 || result.is_null() {
            return None;
        }
        Some(CStr::from_ptr(pwd.pw_name).to_string_lossy().into_owned())
    }
}

fn lookup_group(gid: u32) -> Option<(String, Vec<String>)> {
    unsafe {
        let mut buf = vec![0 as libc::c_char; 65536];
        let mut grp: libc::group = std::mem::zeroed();
        let mut result: *mut libc::group = std::ptr::null_mut();
        let rc = libc::getgrgid_r(gid, &mut grp, buf.as_mut_ptr(), buf.len(), &mut result);
        if rc != 0 || result.is_null() {
            return None;
        }
        let name = CStr::from_ptr(grp.gr_name).to_string_lossy().into_owned();
        let mut members = Vec::new();
        let mut p = grp.gr_mem;
        if !p.is_null() {
            while !(*p).is_null() {
                members.push(CStr::from_ptr(*p).to_string_lossy().into_owned());
                p = p.add(1);
            }
        }
        Some((name, members))
    }
}

impl OwnerMan {
    pub fn new() -> OwnerMan {
        let curr_uid = unsafe { libc::getuid() };
        OwnerMan {
            users: HashMap::new(),
            groups: HashMap::new(),
            curr_uid,
            curr_name: lookup_user(curr_uid),
        }
    }

    pub fn user_name(&mut self, uid: u32) -> String {
        self.users
            .entry(uid)
            .or_insert_with(|| lookup_user(uid))
            .clone()
            .unwrap_or_else(|| uid.to_string())
    }

    pub fn group_name(&mut self, gid: u32) -> String {
        self.groups
            .entry(gid)
            .or_insert_with(|| lookup_group(gid))
            .as_ref()
            .map(|(n, _)| n.clone())
            .unwrap_or_else(|| gid.to_string())
    }

    pub fn is_curr_user(&self, uid: u32) -> bool {
        uid == self.curr_uid
    }

    pub fn is_curr_group(&mut self, gid: u32) -> bool {
        let name = match &self.curr_name {
            Some(n) => n.clone(),
            None => return false,
        };
        match self.groups.entry(gid).or_insert_with(|| lookup_group(gid)) {
            Some((_, members)) => members.iter().any(|m| *m == name),
            None => false,
        }
    }
}
