//! File-system nodes and their presentation.

use std::fs::Metadata;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use crate::cli::Args;
use crate::config::{Collapse, Conf};
use crate::enums::{DetailField, SortBase, SortField, Typ, Unit};
use crate::owner::OwnerMan;
use crate::style::{self, wrap};

pub struct Node {
    /// The name shown to the user.
    pub display: String,
    /// The name used for matching specs and sorting.
    pub name: String,
    pub path: PathBuf,
    pub meta: Metadata,
    pub typ: Typ,
    pub importance: i8,
    pub spec_styles: Vec<String>,
    pub spec_icons: Vec<Vec<String>>,
    pub collapse: Option<Collapse>,
    pub children: Vec<Node>,
}

pub enum SymState {
    Ok(PathBuf, String),
    Broken(String),
    Cyclic(String),
    Error(std::io::Error),
}

pub struct RenderCtx<'a> {
    pub conf: &'a Conf,
    pub args: &'a Args,
    pub align: bool,
    pub offset: time::UtcOffset,
}

impl Node {
    pub fn new(display: String, name: String, path: PathBuf, meta: Metadata) -> Node {
        let typ = Typ::from_file_type(&meta.file_type());
        Node {
            display,
            name,
            path,
            meta,
            typ,
            importance: 0,
            spec_styles: Vec::new(),
            spec_icons: Vec::new(),
            collapse: None,
            children: Vec::new(),
        }
    }

    pub fn apply_conf(&mut self, conf: &Conf) {
        for spec in &conf.specs {
            if spec.pattern.is_match(&self.name) {
                if let Some(imp) = spec.importance {
                    self.importance = imp;
                }
                if let Some(s) = &spec.style {
                    self.spec_styles.push(s.clone());
                }
                if let Some(icons) = &spec.icons {
                    self.spec_icons.push(icons.clone());
                }
                if let Some(c) = &spec.collapse {
                    self.collapse = Some(c.clone());
                }
            }
        }
    }

    /// Relative importance compared to the cutoff.
    pub fn rel_imp(&self, args: &Args) -> i32 {
        self.importance as i32 - args.imp as i32
    }

    pub fn is_imp_hidden(&self, conf: &Conf, args: &Args) -> bool {
        match conf.imp_styles.iter().map(|(k, _)| *k as i32).min() {
            Some(min) => self.rel_imp(args) < min,
            None => false,
        }
    }

    fn imp_style(&self, conf: &Conf, args: &Args) -> String {
        let keys: Vec<i32> = conf.imp_styles.iter().map(|(k, _)| *k as i32).collect();
        let (min, max) = match (keys.iter().min(), keys.iter().max()) {
            (Some(a), Some(b)) => (*a, *b),
            _ => return String::new(),
        };
        let rel = self.rel_imp(args).clamp(min, max);
        conf.imp_styles
            .iter()
            .find(|(k, _)| *k as i32 == rel)
            .map(|(_, s)| s.clone())
            .unwrap_or_default()
    }

    /// The combined style directives for the node.
    pub fn directives(&self, conf: &Conf, args: &Args) -> String {
        let mut parts = vec![conf.typ_info(self.typ).style, self.imp_style(conf, args)];
        parts.extend(self.spec_styles.iter().cloned());
        parts.join(" ")
    }

    pub fn icon(&self, conf: &Conf) -> String {
        for icons in self.spec_icons.iter().rev() {
            for name in icons {
                if let Some(g) = conf.icons.get(name) {
                    return g.clone();
                }
            }
        }
        for name in &conf.typ_info(self.typ).icons {
            if let Some(g) = conf.icons.get(name) {
                return g.clone();
            }
        }
        String::new()
    }

    pub fn is_dir(&self) -> bool {
        self.typ == Typ::Dir
    }

    // -----------------------------------------------------------------------
    // Symlinks
    // -----------------------------------------------------------------------

    pub fn sym_state(&self) -> Option<SymState> {
        if self.typ != Typ::Symlink {
            return None;
        }
        let target = match std::fs::read_link(&self.path) {
            Ok(t) => t,
            Err(e) => return Some(SymState::Error(e)),
        };
        let target_str = target.to_string_lossy().into_owned();
        match std::fs::metadata(&self.path) {
            Ok(_) => {
                let resolved = match self.path.parent() {
                    Some(p) => p.join(&target),
                    None => target.clone(),
                };
                Some(SymState::Ok(resolved, target_str))
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    Some(SymState::Broken(target_str))
                } else if e.raw_os_error() == Some(libc::ELOOP) {
                    Some(SymState::Cyclic(target_str))
                } else {
                    Some(SymState::Error(e))
                }
            }
        }
    }

    fn sym_part(path: &Path, state: SymState, conf: &Conf, depth: usize) -> String {
        let info = |k: &str| conf.symlink.get(k).cloned().unwrap_or_default();
        match state {
            SymState::Ok(resolved, text) => {
                let i = info("ok");
                let (typ_style, next) = match std::fs::symlink_metadata(&resolved) {
                    Ok(m) => {
                        let t = Typ::from_file_type(&m.file_type());
                        let next = if t == Typ::Symlink && depth < 64 {
                            let tmp = Node::new(String::new(), String::new(), resolved.clone(), m);
                            tmp.sym_state()
                                .map(|s| Node::sym_part(&resolved, s, conf, depth + 1))
                                .unwrap_or_default()
                        } else {
                            String::new()
                        };
                        (conf.typ_info(t).style, next)
                    }
                    Err(_) => (String::new(), String::new()),
                };
                let _ = path;
                format!(" {} {}{}", wrap(&i.style, &i.sep), wrap(&typ_style, &text), next)
            }
            SymState::Broken(text) => {
                let i = info("broken");
                format!(" <{}>{} <strikethrough>{}</></>", i.style, i.sep, text)
            }
            SymState::Cyclic(text) => {
                let i = info("cyclic");
                let sty = conf.typ_info(Typ::Symlink).style;
                format!(" <{}>{} <{}>{}</></>", i.style, i.sep, sty, text)
            }
            SymState::Error(e) => {
                let i = info("error");
                format!(" <{}>{} <bold red>error:</> {}</>", i.style, i.sep, e)
            }
        }
    }

    // -----------------------------------------------------------------------
    // Name cell
    // -----------------------------------------------------------------------

    /// Build the markup for the name of the node.
    pub fn name_cell(&self, ctx: &RenderCtx, tree_prefix: &str, show_sym: bool) -> String {
        let conf = ctx.conf;
        let args = ctx.args;
        let directives = self.directives(conf, args);
        let mut out = String::new();
        out.push_str(tree_prefix);
        if !style::is_hidden(&directives) {
            if args.icon {
                let icon = self.icon(conf);
                let w = style::width(&icon);
                let pad = if w < 1 { " " } else { "" };
                out.push_str(&format!(
                    "<{}>{}{} </>",
                    style::icon_directives(&directives),
                    icon,
                    pad
                ));
            }
            let mut name: &str = &self.display;
            if ctx.align {
                if let Some(rest) = name.strip_prefix('.') {
                    out.push_str("<dimmed>.</>");
                    name = rest;
                } else {
                    out.push(' ');
                }
            }
            let suffix = if args.suffix {
                conf.typ_info(self.typ).suffix
            } else {
                String::new()
            };
            out.push_str(&format!("<{}>{}{}</>", directives, name, suffix));
        }
        if show_sym && args.sym {
            if let Some(state) = self.sym_state() {
                out.push_str(&Node::sym_part(&self.path, state, conf, 0));
            }
        }
        out
    }

    // -----------------------------------------------------------------------
    // Details
    // -----------------------------------------------------------------------

    pub fn detail_cell(&self, field: DetailField, ctx: &RenderCtx, owners: &mut OwnerMan) -> String {
        let conf = ctx.conf;
        let m = &self.meta;
        match field {
            DetailField::Dev => wrap(&conf.dev_style, &m.dev().to_string()),
            DetailField::Ino => wrap(&conf.ino_style, &m.ino().to_string()),
            DetailField::Nlink => {
                let n = m.nlink();
                let idx = match (self.is_dir(), n == 1) {
                    (false, true) => 0,
                    (false, false) => 1,
                    (true, true) => 2,
                    (true, false) => 3,
                };
                wrap(&conf.nlink_styles[idx], &n.to_string())
            }
            DetailField::Typ => {
                let info = conf.typ_info(self.typ);
                wrap(&info.style, &info.ch)
            }
            DetailField::Perm => self.perm_cell(conf),
            DetailField::Oct => self.oct_cell(conf),
            DetailField::User => {
                let uid = m.uid();
                let st = if owners.is_curr_user(uid) {
                    &conf.user_styles.curr
                } else {
                    &conf.user_styles.other
                };
                wrap(st, &owners.user_name(uid))
            }
            DetailField::Uid => {
                let uid = m.uid();
                let st = if owners.is_curr_user(uid) {
                    &conf.user_styles.curr
                } else {
                    &conf.user_styles.other
                };
                wrap(st, &uid.to_string())
            }
            DetailField::Group => {
                let gid = m.gid();
                let st = if owners.is_curr_group(gid) {
                    conf.group_styles.curr.clone()
                } else {
                    conf.group_styles.other.clone()
                };
                wrap(&st, &owners.group_name(gid))
            }
            DetailField::Gid => {
                let gid = m.gid();
                let st = if owners.is_curr_group(gid) {
                    conf.group_styles.curr.clone()
                } else {
                    conf.group_styles.other.clone()
                };
                wrap(&st, &gid.to_string())
            }
            DetailField::Size => {
                if self.is_dir() {
                    String::new()
                } else {
                    size_cell(m.size(), ctx.args.unit, conf)
                }
            }
            DetailField::Blocks => {
                if self.is_dir() {
                    String::new()
                } else {
                    wrap(&conf.blocks_style, &m.blocks().to_string())
                }
            }
            DetailField::Btime | DetailField::Ctime | DetailField::Mtime | DetailField::Atime => {
                match self.time(field) {
                    Some(t) => {
                        let fmt = conf
                            .timestamp_formats
                            .get(field.key())
                            .cloned()
                            .unwrap_or_default();
                        format_time(t, &fmt, ctx.offset)
                    }
                    None => String::new(),
                }
            }
            DetailField::Git => String::new(),
            DetailField::Name => String::new(),
        }
    }

    pub fn time(&self, field: DetailField) -> Option<SystemTime> {
        let m = &self.meta;
        match field {
            DetailField::Btime => m.created().ok(),
            DetailField::Ctime => {
                let secs = m.ctime();
                let nsecs = m.ctime_nsec();
                if secs >= 0 {
                    Some(SystemTime::UNIX_EPOCH + std::time::Duration::new(secs as u64, nsecs as u32))
                } else {
                    SystemTime::UNIX_EPOCH
                        .checked_sub(std::time::Duration::from_secs((-secs) as u64))
                        .map(|t| t + std::time::Duration::from_nanos(nsecs as u64))
                }
            }
            DetailField::Mtime => m.modified().ok(),
            DetailField::Atime => m.accessed().ok(),
            _ => None,
        }
    }

    fn perm_cell(&self, conf: &Conf) -> String {
        let mode = self.meta.permissions().mode();
        let st = |k: &str| conf.perm_styles.get(k).cloned().unwrap_or_default();
        let mut groups: Vec<String> = Vec::new();
        let specials = [(0o4000, 's', 'S'), (0o2000, 's', 'S'), (0o1000, 't', 'T')];
        for (i, shift) in [6u32, 3, 0].iter().enumerate() {
            let bits = (mode >> shift) & 0o7;
            let mut s = String::new();
            let r = if bits & 4 != 0 { ('r', "read") } else { ('-', "none") };
            let w = if bits & 2 != 0 { ('w', "write") } else { ('-', "none") };
            let special = mode & specials[i].0 != 0;
            let x = match (bits & 1 != 0, special) {
                (true, false) => ('x', "execute"),
                (false, false) => ('-', "none"),
                (true, true) => (specials[i].1, "special"),
                (false, true) => (specials[i].2, "special"),
            };
            for (c, k) in [r, w, x] {
                s.push_str(&wrap(&st(k), &c.to_string()));
            }
            groups.push(s);
        }
        groups.join(" ")
    }

    fn oct_cell(&self, conf: &Conf) -> String {
        let mode = self.meta.permissions().mode();
        let st = |k: &str| conf.oct_styles.get(k).cloned().unwrap_or_default();
        let special = (mode >> 9) & 0o7;
        let mut s = String::new();
        if special == 0 {
            s.push(' ');
        } else {
            s.push_str(&wrap(&st("special"), &special.to_string()));
        }
        s.push_str(&wrap(&st("user"), &((mode >> 6) & 0o7).to_string()));
        s.push_str(&wrap(&st("group"), &((mode >> 3) & 0o7).to_string()));
        s.push_str(&wrap(&st("other"), &(mode & 0o7).to_string()));
        s
    }

    // -----------------------------------------------------------------------
    // Sorting
    // -----------------------------------------------------------------------

    pub fn cname(&self) -> String {
        self.name
            .to_lowercase()
            .trim_start_matches(|c: char| !c.is_alphanumeric())
            .to_string()
    }

    pub fn ext(&self) -> String {
        Path::new(&self.name)
            .extension()
            .map(|e| e.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    pub fn compare(&self, other: &Node, bases: &[SortBase], owners: &mut OwnerMan) -> std::cmp::Ordering {
        use std::cmp::Ordering;
        for b in bases {
            let ord = self.compare_field(other, b.field, owners);
            let ord = if b.reverse { ord.reverse() } else { ord };
            if ord != Ordering::Equal {
                return ord;
            }
        }
        Ordering::Equal
    }

    fn compare_field(&self, other: &Node, field: SortField, owners: &mut OwnerMan) -> std::cmp::Ordering {
        let a = &self.meta;
        let b = &other.meta;
        match field {
            SortField::Dev => a.dev().cmp(&b.dev()),
            SortField::Ino => a.ino().cmp(&b.ino()),
            SortField::Nlink => a.nlink().cmp(&b.nlink()),
            SortField::Typ => self.typ.cmp(&other.typ),
            SortField::Cat => {
                let ca = if self.is_dir() { 0 } else { 1 };
                let cb = if other.is_dir() { 0 } else { 1 };
                ca.cmp(&cb)
            }
            SortField::User => owners.user_name(a.uid()).cmp(&owners.user_name(b.uid())),
            SortField::Uid => a.uid().cmp(&b.uid()),
            SortField::Group => owners.group_name(a.gid()).cmp(&owners.group_name(b.gid())),
            SortField::Gid => a.gid().cmp(&b.gid()),
            SortField::Size => a.size().cmp(&b.size()),
            SortField::Blocks => a.blocks().cmp(&b.blocks()),
            SortField::Btime => self.time(DetailField::Btime).cmp(&other.time(DetailField::Btime)),
            SortField::Ctime => self.time(DetailField::Ctime).cmp(&other.time(DetailField::Ctime)),
            SortField::Mtime => self.time(DetailField::Mtime).cmp(&other.time(DetailField::Mtime)),
            SortField::Atime => self.time(DetailField::Atime).cmp(&other.time(DetailField::Atime)),
            SortField::Name => self.name.cmp(&other.name),
            SortField::Cname => self.cname().cmp(&other.cname()),
            SortField::Ext => self.ext().cmp(&other.ext()),
        }
    }
}

fn size_cell(size: u64, unit: Unit, conf: &Conf) -> String {
    let [mag_st, prefix_st, base_st] = &conf.size_styles;
    match unit {
        Unit::None => format!("{} {}", wrap(mag_st, &size.to_string()), wrap(base_st, "B")),
        Unit::Binary | Unit::Decimal => {
            let (kilo, prefixes, pw): (f64, [&str; 8], usize) = if unit == Unit::Binary {
                (1024.0, ["Ki", "Mi", "Gi", "Ti", "Pi", "Ei", "Zi", "Yi"], 2)
            } else {
                (1000.0, ["k", "M", "G", "T", "P", "E", "Z", "Y"], 1)
            };
            let mut amount = size as f64;
            let prefix = if amount < kilo {
                ""
            } else {
                let mut idx = 0;
                while amount >= kilo && idx < 8 {
                    amount /= kilo;
                    idx += 1;
                }
                prefixes[idx - 1]
            };
            let mag = format!("{:.1}", amount);
            let prefix = format!("{:>width$}", prefix, width = pw);
            format!(
                "{} {}{}",
                wrap(mag_st, &mag),
                wrap(prefix_st, &prefix),
                wrap(base_st, "B")
            )
        }
    }
}

fn format_time(t: SystemTime, fmt: &str, offset: time::UtcOffset) -> String {
    let dt = time::OffsetDateTime::from(t).to_offset(offset);
    let desc = crate::fmt_time::parse(fmt);
    dt.format(&desc).unwrap()
}
