//! File-system nodes and their presentation.

use std::fs::Metadata;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use crate::cli::Args;
use crate::config::{Collapse, Conf};
use crate::enums::{DetailField, SortBase, SortField, Typ, Unit};
use crate::owner::OwnerMan;
use crate::style::{self, wrap};

pub struct Node {
    /// The name shown to the user.
    pub display: String,
    /// The name used for matching specs and sorting.
    pub name: String,
    pub path: PathBuf,
    pub meta: Metadata,
    pub typ: Typ,
    pub importance: i8,
    pub spec_styles: Vec<String>,
    pub spec_icons: Vec<Vec<String>>,
    pub collapse: Option<Collapse>,
    pub children: Vec<Node>,
}

pub enum SymState {
    Ok(PathBuf, String),
    Broken(String),
    Cyclic(String),
    Error(std::io::Error),
}

pub struct RenderCtx<'a> {
    pub conf: &'a Conf,
    pub args: &'a Args,
    pub align: bool,
    pub offset: time::UtcOffset,
}

impl Node {
    pub fn new(display: String, name: String, path: PathBuf, meta: Metadata) -> Node {
        let typ = Typ::from_file_type(&meta.file_type());
        Node {
            display,
            name,
            path,
            meta,
            typ,
            importance: 0,
            spec_styles: Vec::new(),
            spec_icons: Vec::new(),
            collapse: None,
            children: Vec::new(),
        }
    }

    pub fn apply_conf(&mut self, conf: &Conf) {
        for spec in &conf.specs {
            if spec.pattern.is_match(&self.name) {
                if let Some(imp) = spec.importance {
                    self.importance = imp;
                }
                if let Some(s) = &spec.style {
                    self.spec_styles.push(s.clone());
                }
                if let Some(icons) = &spec.icons {
                    self.spec_icons.push(icons.clone());
                }
                if let Some(c) = &spec.collapse {
                    self.collapse = Some(c.clone());
                }
            }
        }
    }

    /// Relative importance compared to the cutoff.
    pub fn rel_imp(&self, args: &Args) -> i32 {
        self.importance as i32 - args.imp as i32
    }

    pub fn is_imp_hidden(&self, conf: &Conf, args: &Args) -> bool {
        match conf.imp_styles.iter().map(|(k, _)| *k as i32).min() {
            Some(min) => self.rel_imp(args) < min,
            None => false,
        }
    }

    fn imp_style(&self, conf: &Conf, args: &Args) -> String {
        let keys: Vec<i32> = conf.imp_styles.iter().map(|(k, _)| *k as i32).collect();
        let (min, max) = match (keys.iter().min(), keys.iter().max()) {
            (Some(a), Some(b)) => (*a, *b),
            _ => return String::new(),
        };
        let rel = self.rel_imp(args).clamp(min, max);
        conf.imp_styles
            .iter()
            .find(|(k, _)| *k as i32 == rel)
            .map(|(_, s)| s.clone())
            .unwrap_or_default()
    }

    /// The combined style directives for the node.
    pub fn directives(&self, conf: &Conf, args: &Args) -> String {
        let mut parts = vec![conf.typ_info(self.typ).style, self.imp_style(conf, args)];
        parts.extend(self.spec_styles.iter().cloned());
        parts.join(" ")
    }

    pub fn icon(&self, conf: &Conf) -> String {
        for icons in self.spec_icons.iter().rev() {
            for name in icons {
                if let Some(g) = conf.icons.get(name) {
                    return g.clone();
                }
            }
        }
        for name in &conf.typ_info(self.typ).icons {
            if let Some(g) = conf.icons.get(name) {
                return g.clone();
            }
        }
        String::new()
    }

    pub fn is_dir(&self) -> bool {
        self.typ == Typ::Dir
    }

    // -----------------------------------------------------------------------
    // Symlinks
    // -----------------------------------------------------------------------

    pub fn sym_state(&self) -> Option<SymState> {
        if self.typ != Typ::Symlink {
            return None;
        }
        let target = match std::fs::read_link(&self.path) {
            Ok(t) => t,
            Err(e) => return Some(SymState::Error(e)),
        };
        let target_str = target.to_string_lossy().into_owned();
        match std::fs::metadata(&self.path) {
            Ok(_) => {
                let resolved = match self.path.parent() {
                    Some(p) => p.join(&target),
                    None => target.clone(),
                };
                Some(SymState::Ok(resolved, target_str))
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    Some(SymState::Broken(target_str))
                } else if e.raw_os_error() == Some(libc::ELOOP) {
                    Some(SymState::Cyclic(target_str))
                } else {
                    Some(SymState::Error(e))
                }
            }
        }
    }

    fn sym_part(path: &Path, state: SymState, conf: &Conf, depth: usize) -> String {
        let info = |k: &str| conf.symlink.get(k).cloned().unwrap_or_default();
        match state {
            SymState::Ok(resolved, text) => {
                let i = info("ok");
                let (typ_style, next) = match std::fs::symlink_metadata(&resolved) {
                    Ok(m) => {
                        let t = Typ::from_file_type(&m.file_type());
                        let next = if t == Typ::Symlink && depth < 64 {
                            let tmp = Node::new(String::new(), String::new(), resolved.clone(), m);
                            tmp.sym_state()
                                .map(|s| Node::sym_part(&resolved, s, conf, depth + 1))
                                .unwrap_or_default()
                        } else {
