            DetailField::Nlink => {
                let n = m.nlink();
                let idx = match (self.is_dir(), n == 1) {
                    (false, true) => 0,
                    (false, false) => 1,
                    (true, true) => 2,
                    (true, false) => 3,
                };
                wrap(&conf.nlink_styles[idx], &n.to_string())
            }
            DetailField::Typ => {
                let info = conf.typ_info(self.typ);
                wrap(&info.style, &info.ch)
            }
            DetailField::Perm => self.perm_cell(conf),
            DetailField::Oct => self.oct_cell(conf),
            DetailField::User => {
                let uid = m.uid();
                let st = if owners.is_curr_user(uid) {
                    &conf.user_styles.curr
                } else {
                    &conf.user_styles.other
                };
                wrap(st, &owners.user_name(uid))
            }
            DetailField::Uid => {
                let uid = m.uid();
                let st = if owners.is_curr_user(uid) {
