//! Rendering of node collections as lists, tables and grids.

use crate::config::Conf;
use crate::enums::DetailField;
use crate::node::{Node, RenderCtx};
use crate::owner::OwnerMan;
use crate::style;

/// A node paired with its tree prefix.
pub struct Entry<'a> {
    pub node: &'a Node,
    pub prefix: String,
}

/// Flatten a forest of nodes into entries with tree prefixes.
pub fn flatten<'a>(nodes: &'a [Node], conf: &Conf, align: bool) -> Vec<Entry<'a>> {
    let mut out = Vec::new();
    let unit = if align { "   " } else { "  " };
    fn walk<'a>(nodes: &'a [Node], parent_prefix: Option<&str>, conf: &Conf, unit: &str, out: &mut Vec<Entry<'a>>) {
        let n = nodes.len();
        for (i, node) in nodes.iter().enumerate() {
            let last = i + 1 == n;
            let prefix = match parent_prefix {
                None => String::new(),
                Some(pp) => {
                    let conn = if last { &conf.tree[3] } else { &conf.tree[2] };
                    format!("{}{}{}", pp, unit, conn)
                }
            };
            // The prefix inherited by this node's children.
            let child_base = match parent_prefix {
                None => String::new(),
                Some(pp) => {
                    let cont = if last { &conf.tree[1] } else { &conf.tree[0] };
                    format!("{}{}{}", pp, unit, cont)
                }
            };
            out.push(Entry { node, prefix });
            if !node.children.is_empty() {
                walk(&node.children, Some(&child_base), conf, unit, out);
            }
        }
    }
    walk(nodes, None, conf, unit, &mut out);
    out
}

pub fn print_list(entries: &[Entry], ctx_for: &dyn Fn(&Node) -> RenderCtx<'_>) {
    for e in entries {
        let ctx = ctx_for(e.node);
        println!("{}", style::render(&e.node.name_cell(&ctx, &e.prefix, true)));
    }
}

pub fn print_table(
    entries: &[Entry],
    fields: &[DetailField],
    header: bool,
    group_conf: &Conf,
    ctx_for: &dyn Fn(&Node) -> RenderCtx<'_>,
    owners: &mut OwnerMan,
) {
    let mut cols: Vec<DetailField> = fields.to_vec();
    cols.push(DetailField::Name);
    let mut rows: Vec<Vec<String>> = Vec::new();
    for e in entries {
        let ctx = ctx_for(e.node);
        let mut row = Vec::new();
        for f in &cols {
            if *f == DetailField::Name {
                row.push(e.node.name_cell(&ctx, &e.prefix, true));
            } else {
                row.push(e.node.detail_cell(*f, &ctx, owners));
            }
        }
        rows.push(row);
    }
    let headers: Vec<String> = cols.iter().map(|f| group_conf.column_name(*f)).collect();
    let mut widths = vec![0usize; cols.len()];
    if header {
        for (i, h) in headers.iter().enumerate() {
            widths[i] = widths[i].max(style::width(h));
        }
    }
    for row in &rows {
        for (i, c) in row.iter().enumerate() {
            widths[i] = widths[i].max(style::width(c));
        }
    }
    let last = cols.len() - 1;
    let fmt_cell = |i: usize, content: &str| -> String {
        if i == last {
            return content.to_string();
        }
        let w = style::width(content);
        let pad = " ".repeat(widths[i].saturating_sub(w));
        if cols[i].right_aligned() {
            format!("{}{} ", pad, content)
        } else {
            format!("{}{} ", content, pad)
        }
    };
    if header {
        let mut line = String::new();
        for (i, h) in headers.iter().enumerate() {
            line.push_str(&style::render(&format!(
                "<{}>{}</>",
                group_conf.header_style,
                fmt_cell(i, h)
            )));
        }
        println!("{}", line);
    }
    for row in &rows {
        let mut line = String::new();
        for (i, c) in row.iter().enumerate() {
            line.push_str(&style::render(&fmt_cell(i, c)));
        }
        println!("{}", line);
    }
}

pub fn print_grid(
    nodes: &[&Node],
    down: bool,
    term_width: Option<usize>,
    ctx_for: &dyn Fn(&Node) -> RenderCtx<'_>,
) {
    let cells: Vec<String> = nodes
        .iter()
        .map(|n| {
            let ctx = ctx_for(n);
            n.name_cell(&ctx, "", false)
        })
        .collect();
    if cells.is_empty() {
        return;
    }
    let widths: Vec<usize> = cells.iter().map(|c| style::width(c)).collect();
    let max_w = *widths.iter().max().unwrap_or(&0);
    let sep = 2usize;
    let cols = match term_width {
        Some(tw) => ((tw + sep) / (max_w + sep)).max(1),
        None => 1,
    };
    if cols <= 1 {
        for c in &cells {
            println!("{}", style::render(c));
        }
        return;
    }
    let n = cells.len();
    let order: Vec<usize> = if down {
        let rows = (n + cols - 1) / cols;
        let mut v = Vec::with_capacity(n);
        for r in 0..rows {
            for c in 0..cols {
                let idx = c * rows + r;
                if idx < n {
                    v.push(idx);
                }
            }
        }
        v
    } else {
        (0..n).collect()
    };
    for chunk in order.chunks(cols) {
        let mut line = String::new();
        let k = chunk.len();
        for (j, &idx) in chunk.iter().enumerate() {
            let pad = " ".repeat(max_w.saturating_sub(widths[idx]));
            let sep_s = if j + 1 < k { "  " } else { "" };
            line.push_str(&style::render(&format!("{}{}{}", cells[idx], pad, sep_s)));
        }
        println!("{}", line);
    }
}
EOF
echo ok"}

