        "{}",
        style::render(&format!("<bold>{}</>:\n\t<bold red>error:</> {}", p, msg))
    );
}

fn parent_of(path: &Path) -> PathBuf {
    match path.parent() {
        Some(p) => p.to_path_buf(),
        None => path.to_path_buf(),
    }
}

/// Arrange nodes into a forest based on their collapse specs.
fn collapse_nodes(nodes: Vec<Node>) -> Vec<Node> {
    let n = nodes.len();
    let mut index: HashMap<String, usize> = HashMap::new();
    for (i, node) in nodes.iter().enumerate() {
        index.entry(node.name.clone()).or_insert(i);
    }
    let mut parent: Vec<Option<usize>> = vec![None; n];
    for (i, node) in nodes.iter().enumerate() {
        let target = match &node.collapse {
            Some(Collapse::Name(name)) => Some(name.clone()),
            Some(Collapse::Ext(ext)) => {
                let stem = Path::new(&node.name)
                    .file_stem()
                    .map(|s| s.to_string_lossy().into_owned())
                    .unwrap_or_default();
                Some(format!("{}.{}", stem, ext))
            }
            None => None,
        };
        if let Some(t) = target {
            if let Some(&j) = index.get(&t) {
                if j != i {
                    parent[i] = Some(j);
                }
            }
        }
    }
    // Break cycles.
    for i in 0..n {
        let mut seen = vec![false; n];
        let mut cur = i;
        seen[cur] = true;
        while let Some(p) = parent[cur] {
            if seen[p] {
                parent[i] = None;
                break;
            }
            seen[p] = true;
            cur = p;
        }
    }
    let mut slots: Vec<Option<Node>> = nodes.into_iter().map(Some).collect();
    // Attach children deepest-first by repeatedly moving leaves.
    let mut children_of: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n {
        if let Some(p) = parent[i] {
            children_of[p].push(i);
        }
    }
    fn build(i: usize, slots: &mut Vec<Option<Node>>, children_of: &Vec<Vec<usize>>) -> Node {
        let mut node = slots[i].take().unwrap();
        for &c in &children_of[i] {
            let child = build(c, slots, children_of);
            node.children.push(child);
        }
        node
    }
    let mut out = Vec::new();
    for i in 0..n {
        if parent[i].is_none() {
            out.push(build(i, &mut slots, &children_of));
        }
    }
    out
}

fn sort_nodes(nodes: &mut Vec<Node>, sorts: &[enums::SortBase], owners: &mut OwnerMan) {
    nodes.sort_by(|a, b| a.compare(b, sorts, owners));
    for n in nodes.iter_mut() {
        if !n.children.is_empty() {
            sort_nodes(&mut n.children, sorts, owners);
        }
    }
}

fn common_base(paths: &[PathBuf], cwd: &Path) -> PathBuf {
    let abs: Vec<PathBuf> = paths
        .iter()
        .map(|p| config::normalize(&cwd.join(p)))
        .collect();
    let mut common: Vec<std::ffi::OsString> = abs[0]
        .components()
        .map(|c| c.as_os_str().to_os_string())
        .collect();
    for p in &abs[1..] {
        let comps: Vec<std::ffi::OsString> =
            p.components().map(|c| c.as_os_str().to_os_string()).collect();
        let mut k = 0;
        while k < common.len() && k < comps.len() && common[k] == comps[k] {
            k += 1;
        }
        common.truncate(k);
    }
    let common: PathBuf = common.iter().collect();
    let is_dir = fs::symlink_metadata(&common)
        .map(|m| m.is_dir())
        .unwrap_or(false);
    if is_dir {
        common
    } else {
        parent_of(&common)
    }
}

fn main() {
    let args = cli::parse();
    let fields = args.detail_fields();
    let typs = args.typ_set();
    let sorts = args.sorts();
    let cwd = std::env::current_dir().unwrap_or_default();
    let offset = local_offset();
    let mut confman = ConfMan::new();
    let mut owners = OwnerMan::new();
    let multi = args.paths.len() > 1;

    let mut files: Vec<(Node, Rc<Conf>)> = Vec::new();
    let mut file_paths: Vec<PathBuf> = Vec::new();
    let mut dirs: Vec<(PathBuf, Rc<Conf>)> = Vec::new();

    for path in &args.paths {
        let meta = fs::symlink_metadata(path);
        let is_dir = meta.as_ref().map(|m| m.is_dir()).unwrap_or(false);
        let base = if is_dir { path.clone() } else { parent_of(path) };
        let conf = match confman.get(&base) {
            Ok(c) => c,
            Err(msg) => {
                print_input_error(path, &msg);
                continue;
            }
        };
        let meta = match meta {
            Ok(m) => m,
            Err(e) => {
                print_input_error(path, &e.to_string());
                continue;
            }
        };
        if is_dir {
            dirs.push((path.clone(), conf));
        } else {
            let display = path.to_string_lossy().into_owned();
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_else(|| display.clone());
            let mut node = Node::new(display, name, path.clone(), meta);
            node.apply_conf(&conf);
            files.push((node, conf));
            file_paths.push(path.clone());
        }
    }

    let term_width = stdout_width();

    if !files.is_empty() {
        let confs: HashMap<*const Node, Rc<Conf>> = files
            .iter()
            .map(|(n, c)| (n as *const Node, c.clone()))
            .collect();
        let ctx_for = |n: &Node| -> RenderCtx<'_> {
            let c: &Conf = confs.get(&(n as *const Node)).map(|c| c.as_ref()).unwrap();
            // SAFETY of lifetimes: confs outlives every use of the context.
            let c: &Conf = unsafe { &*(c as *const Conf) };
            RenderCtx {
                conf: c,
                args: &args,
                align: false,
                offset,
            }
        };
        let nodes: Vec<&Node> = files.iter().map(|(n, _)| n).collect();
        if !fields.is_empty() {
            let base = common_base(&file_paths, &cwd);
            let group_conf = confman
                .get(&base)
                .unwrap_or_else(|_| files[0].1.clone());
            let entries: Vec<output::Entry> = nodes
                .iter()
                .map(|n| output::Entry {
                    node: n,
                    prefix: String::new(),
                })
                .collect();
            output::print_table(&entries, &fields, args.header, &group_conf, &ctx_for, &mut owners);
        } else if args.grid {
            output::print_grid(&nodes, args.down, term_width, &ctx_for);
        } else {
            let entries: Vec<output::Entry> = nodes
                .iter()
                .map(|n| output::Entry {
                    node: n,
                    prefix: String::new(),
                })
                .collect();
            output::print_list(&entries, &ctx_for);
        }
    }

    for (path, conf) in &dirs {
        if multi {
            println!();
            println!(
                "{}",
                style::render(&format!("<bold>{}:</>", path.to_string_lossy()))
            );
        }
        let rd = match fs::read_dir(path) {
            Ok(rd) => rd,
            Err(e) => {
                println!("{}", style::render(&format!("<bold red>error:</> {}", e)));
                continue;
            }
        };
        let mut nodes: Vec<Node> = Vec::new();
        for entry in rd.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let p = entry.path();
            let meta = match fs::symlink_metadata(&p) {
                Ok(m) => m,
                Err(_) => continue,
            };
            let mut node = Node::new(name.clone(), name, p, meta);
            node.apply_conf(conf);
            if !typs.contains(&node.typ) {
                continue;
            }
            if let Some(re) = &args.only {
                if !re.is_match(&node.name) {
                    continue;
                }
            }
            if let Some(re) = &args.exclude {
                if re.is_match(&node.name) {
                    continue;
                }
            }
            if node.is_imp_hidden(conf, &args) {
                continue;
            }
            nodes.push(node);
        }
        let use_grid = fields.is_empty() && args.grid;
        if args.collapse && !use_grid {
            nodes = collapse_nodes(nodes);
        }
        sort_nodes(&mut nodes, &sorts, &mut owners);
        let conf_ref: &Conf = conf.as_ref();
        let ctx_for = |_n: &Node| -> RenderCtx<'_> {
            RenderCtx {
                conf: conf_ref,
                args: &args,
                align: args.align,
                offset,
            }
        };
        if !fields.is_empty() {
            let entries = output::flatten(&nodes, conf_ref, args.align);
            output::print_table(&entries, &fields, args.header, conf_ref, &ctx_for, &mut owners);
        } else if args.grid {
            let refs: Vec<&Node> = nodes.iter().collect();
            output::print_grid(&refs, args.down, term_width, &ctx_for);
        } else {
            let entries = output::flatten(&nodes, conf_ref, args.align);
            output::print_list(&entries, &ctx_for);
        }
    }
}
