new='''/// Arrange nodes into a forest based on their collapse specs.
fn collapse_nodes(nodes: Vec<Node>) -> Vec<Node> {
    let names: std::collections::HashSet<String> = nodes.iter().map(|n| n.name.clone()).collect();
    let mut roots: Vec<Node> = Vec::new();
    // Children waiting for their principal, keyed by the principal's name,
    // in the order of insertion.
    let mut pending: Vec<(String, Vec<Node>)> = Vec::new();
    for node in nodes {
        let target = match &node.collapse {
            Some(Collapse::Name(name)) => Some(name.clone()),
            Some(Collapse::Ext(ext)) => {
                let stem = Path::new(&node.name)
                    .file_stem()
                    .map(|s| s.to_string_lossy().into_owned())
                    .unwrap_or_default();
                Some(format!("{}.{}", stem, ext))
            }
            None => None,
        };
        match target {
            Some(t) if names.contains(&t) => match pending.iter_mut().find(|(k, _)| *k == t) {
                Some((_, v)) => v.push(node),
                None => pending.push((t, vec![node])),
            },
            _ => roots.push(node),
        }
    }
    fn attach(node: &mut Node, pending: &mut Vec<(String, Vec<Node>)>) {
        if let Some(pos) = pending.iter().position(|(k, _)| *k == node.name) {
            let (_, mut children) = pending.remove(pos);
            for c in children.iter_mut() {
                attach(c, pending);
            }
            node.children = children;
        }
    }
    for r in roots.iter_mut() {
        attach(r, &mut pending);
    }
    // Nodes that could not be attached (cycles) are shown at the top level.
    for (_, v) in pending {
        roots.extend(v);
    }
    roots
}

fn sort_nodes(nodes: &mut Vec<Node>, sorts: &[enums::SortBase], owners: &mut OwnerMan) {
    nodes.sort_by(|a, b| a.compare(b, sorts, owners));
    for n in nodes.iter_mut() {
        n.children.sort_by(|a, b| a.compare(b, sorts, owners));
    }
}

