/// Determine the working directory of the git repository at `dir`, if
/// `dir` contains a valid `.git` entry.
fn repo_at(dir: &Path) -> bool {
    let dotgit = dir.join(".git");
    let meta = match std::fs::metadata(&dotgit) {
        Ok(m) => m,
        Err(_) => return false,
    };
    if meta.is_dir() {
        return is_git_dir(&dotgit);
    }
    if meta.is_file() {
        if let Ok(content) = std::fs::read_to_string(&dotgit) {
